//const item = $input.first().json;
const data = $json;

const context = data.story_context;
const mission = data.act_mission;
const act_number = data.act_number;
const arcPhase = data.arc_phase;

const memory = data.accumulated_memory || "";
const summary = data.accumulated_summary || "";

let prompt = "";

prompt += context + "\n\n";

// resumen solo si existe
if (summary) {
  prompt += "RESUMEN DEL ACTO ANTERIOR\n";
  prompt += summary + "\n\n";
}

// memoria solo si existe
if (memory && typeof memory === "object") {
  prompt += "ESTADO ACTUAL DE LA HISTORIA\n\n";

  prompt += `Ubicación: ${memory.location || "desconocida"}\n`;
  prompt += `Personajes presentes: ${(memory.characters || []).join(", ")}\n`;
  prompt += `Situación actual: ${memory.situation || ""}\n`;
  prompt += `Amenaza activa: ${memory.active_threat || ""}\n`;
  prompt += `Objetivo inmediato: ${memory.goal || ""}\n`;
  prompt += `Última acción realizada: ${memory.last_action || ""}\n\n`;
}

if (act_number > 1) {
  prompt += `
  CONTINUIDAD ESTRICTA

  El capítulo debe comenzar INMEDIATAMENTE después de esta acción:

  ${memory?.last_action || summary}

  Reglas obligatorias:

  - No reiniciar la escena
  - No repetir el juego ni el conteo
  - No reintroducir personajes
  - Continuar en la misma ubicación salvo que la acción implique movimiento
`;
}

prompt += "FASE DEL ARCO NARRATIVO\n";
prompt += arcPhase + "\n\n";

prompt += "MISIÓN DEL ACTO\n";
prompt += mission + "\n\n";

if (act_number > 1) {
  // aquí agregamos la regla crítica del pipeline
  prompt += `REGLAS DE CONTINUIDAD\n
 1. Usa el RESUMEN DEL ACTO ANTERIOR como punto de partida narrativo.\n
 2. El capítulo debe comenzar inmediatamente después de ese momento.\n
 3. Respeta la MEMORIA NARRATIVA: contiene hechos, personajes y lugares ya  establecidos.\n
 4. No contradigas ni cambies información almacenada en la memoria.\n
 5. No reinicies la historia ni repitas escenas ya narradas.\n
 6. Avanza el relato desde la última situación descrita en el resumen.\n
  `;
}

if (act_number === 1) {
  prompt += `
INICIO DE LA HISTORIA\n
Este es el primer capítulo.\n
No existe un acto anterior.\n
Comienza la narración desde el contexto inicial descrito arriba.\n
`;
}

prompt += "Escribe el capítulo siguiendo todas las instrucciones anteriores.";

prompt += `
---
IMPORTANTE: 
- Respondé ÚNICAMENTE con el capítulo en español
- NO incluyas "Thinking Process", análisis ni explicaciones
- NO uses formato JSON
- Solo el texto narrativo
`;

return [
  {
    json: {
      ...data,
      prompt
    }
  }
];

const items = $input.all();
const estado = $('build_data_items').first().json.extract_prompt;

return items.map(item => {

  const base = item.json.base_context;

  return {
    json: {
      id_story: base.id_story,
      story_name: base.story_name,

      total_acts: base.total_acts,
      relator: base.relator,
      act_number: item.json.act_number,
      arc_phase: item.json.arc_phase,

      act_mission: item.json.act_mission,

      system_prompt: base.system_prompt,
      extract_prompt: estado,
      story_context: base.story_context,

      accumulated_summary: "",
      accumulated_memory: ""
    }
  };

});

const items = $input.all();
const storyId = items[0].json.id_story;
let md = "# RELATO COMPLETO\n\n";

function extractChapter(raw) {
  if (!raw) return "[ERROR: capítulo vacío]";

  // Si ya es un string limpio (no contiene JSON), devolverlo directo
  if (!raw.includes('"chapter"')) return raw.trim();

  // Buscar el bloque JSON y extraer el campo "chapter"
  const jsonMatch = raw.match(/\{[\s\S]*?"chapter"\s*:\s*"([\s\S]*?)"\s*\}(?:\s*)$/);
  if (jsonMatch) {
    return jsonMatch[1]
      .replace(/\\n/g, '\n')
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, '\\')
      .trim();
  }

  // Fallback: intentar JSON.parse sobre la última aparición de {...}
  const jsonBlocks = raw.match(/\{[\s\S]*?"chapter"[\s\S]*?\}/g);
  if (jsonBlocks) {
    try {
      const parsed = JSON.parse(jsonBlocks[jsonBlocks.length - 1]);
      if (parsed.chapter) return parsed.chapter.trim();
    } catch (_) {}
  }

  // Si todo falla, devolver el raw para no perder contenido
  return raw.trim();
}

items
  .sort((a, b) => a.json.act_number - b.json.act_number)
  .forEach(item => {
    const chapterText = extractChapter(item.json.chapter);
    md += "## ACTO " + item.json.act_number + "\n\n";
    md += chapterText + "\n\n---\n\n";
  });

return [{
  json: {
    md_text: md,
    story_id: storyId,
    nombre_archivo: "relato_" + storyId + ".md"
  }
}];

const base = $input.first().json;

// ← reemplazá 'story_prompt' por el nombre real del campo
const text = base.story_prompt || base.text || base.content || base.data;

if (!text) {
  throw new Error('Campo de texto no encontrado. Campos disponibles: ' + Object.keys(base).join(', '));
}

// 1. Separar contexto: todo lo que está ANTES del primer "**Acto"
const firstActIndex = text.search(/\*\*Acto\s+\d+/);
const contextPart = text.substring(0, firstActIndex).trim();

const relatorMatch = text.match(/\*\*Relator\*\*:\s*(.+)/i);
const relator = relatorMatch ? relatorMatch[1].trim() : "";

// 2. Separar actos por encabezado **Acto N
const sections = text.substring(firstActIndex).split(/(?=\*\*Acto\s+\d+)/).filter(s => s.trim());

const actos = sections.map(section => {
  const numMatch   = section.match(/\*\*Acto\s+(\d+)/);
  const phaseMatch = section.match(/\(([^)]+)\)/);

  const act_number = numMatch  ? Number(numMatch[1])      : null;
  const arc_phase  = phaseMatch ? phaseMatch[1].trim()    : null;

  // Eliminar la línea del encabezado y limpiar
  const content = section
    .replace(/^\*\*Acto[^\n]*\n?/, '')
    .trim();

  return {
    json: {
      act_number,
      arc_phase,
      act_mission: content,
      base_context: {
        id_story:     base.id_story,
        story_name:   base.story_name,
        total_acts:   base.total_acts,
        relator: relator,
        system_prompt: base.system_prompt,
        story_context: contextPart
      }
    }
  };
});

return actos;

const items = $input.all();

let sistema = "";
let historia = "";
let estados = "";
let config = {};

// 1️⃣ obtener configuración primero
for (const item of items) {
  if (item.json && item.json.total_acts) {
    config = item.json;
    break;
  }
}

// 2️⃣ procesar archivos binarios
for (let i = 0; i < items.length; i++) {

  const item = items[i];

  if (item.binary && item.binary.data) {

    const fileName = item.binary.data.fileName || "";

    const buffer = await this.helpers.getBinaryDataBuffer(i, "data");
    const text = buffer.toString("utf8").trim();

    if (fileName === config.system_prompt_file) {
      sistema = text;
      continue;
    }

    if (fileName === config.story_prompt_file) {
      historia = text;
      continue;
    }

    if (fileName === config.extract_prompt_file) {
      estados = text;
      continue;
    }

  }
}

return [{
  json: {
    id_story: config.id_story,
    story_name: config.story_name,
    total_acts: config.total_acts,
    system_prompt: sistema,
    story_prompt: historia,
    extract_prompt: estados,
    accumulated_summary: "",
    accumulated_memory: ""
  }
}];

const basePrompt = $('prepare_items').first().json.extract_prompt;
const chapter = $node["gen_act"].json.text;
const fullPrompt = `
${basePrompt}
---
CAPÍTULO A ANALIZAR:
${chapter}
---
IMPORTANTE:
Debes responder ÚNICAMENTE con un objeto JSON válido.
El campo "summary" debe contener un resumen breve (2–3 líneas) del capítulo.
Estructura exacta:
{
  "summary": "...",
  "memory": {
    "location": "...",
    "characters": ["..."],
    "situation": "...",
    "active_threat": "...",
    "goal": "...",
    "last_action": "..."
  }
}
No expliques nada.
No agregues texto fuera del JSON.
`;

return [{
  json: {
    ...$json,
    text: fullPrompt
  }
}];

function escape(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/'/g, "''")
    .replace(/\u0000/g, '');
}

function extractJSON(text) {
  if (!text) return "{}";
  // 1. intentar extraer bloque ```json
  const match = text.match(/```json\s*([\s\S]*?)\s*```/);
  if (match) {
    return match[1].trim();
  }
  // 2. fallback: buscar primer { ... }
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    return text.slice(firstBrace, lastBrace + 1);
  }
  return "{}";
}

const chapter = $node["gen_act"].json.text;
const raw = $node["extract_story_state"].json.text;
const cleaned = extractJSON(raw);

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("JSON inválido después de limpieza: " + cleaned);
}

const input = $input.first().json;

return [{
  json: {
    id_story: input.id_story,
    act_number: input.act_number,
    arc_phase: escape(input.arc_phase),
    chapter: escape(chapter),
    summary: escape(parsed.summary || ''),
    memory: escape(JSON.stringify(parsed.memory || {}))
  }
}];

const item = $json;

// estado global persistido dentro del workflow
const globalData = $getWorkflowStaticData('global');

// inicialización segura
if (!globalData.state) {
  globalData.state = {
    summary: "",
    memory: ""
  };
}

// inyectar estado en el item actual
return [{
  json: {
    ...item,
    accumulated_summary: globalData.state.summary,
    accumulated_memory: globalData.state.memory
  }
}];

const item = $json;

const globalData = $getWorkflowStaticData('global');

globalData.state = {
  summary: item.summary,
  memory: JSON.parse(item.memory)
};

return [{
  json: {
    ...item,
    extracted_summary: item.summary,
    extracted_memory: JSON.parse(item.memory)
  }
}];

function extractJSON(text) {
  if (!text) return "{}";

  const match = text.match(/```json\s*([\s\S]*?)\s*```/);
  if (match) {
    return match[1].trim();
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    return text.slice(firstBrace, lastBrace + 1);
  }
  return "{}";
}
const rawLLM = $node["extract_story_state"].json.text;
const parsed = JSON.parse(extractJSON(rawLLM));
const flowData = $node["inject_state"].json;
return [{
  json: {
    ...flowData,
    summary: parsed.summary,
    memory: parsed.memory,
    chapter: flowData.chapter
  }
}];

function extractChapter(text) {
  if (!text || typeof text !== 'string') return "";
  let cleaned = text;
  // Eliminar Thinking Process
  cleaned = cleaned.replace(/Thinking Process[\s\S]*?(?=\n\n|\n[A-Z]|```json|$)/gi, "");

  // Eliminar bloques markdown
  cleaned = cleaned.replace(/```json/g, "").replace(/```/g, "");
  // Buscar si hay un objeto JSON con chapter
  const match = cleaned.match(/\{\s*"chapter"\s*:\s*"([\s\S]*?)"\s*\}/);
  if (match) {
    return match[1];
  }
  // Limpiar y devolver
  return cleaned.replace(/^\n+/, "").trim();
}
// Obtener el texto - el parser puede ponerlo en diferente campo
let rawText = "";
const genActOutput = $node["gen_act"].json;
if (genActOutput.text) {
  rawText = genActOutput.text;
} else if (typeof genActOutput === 'string') {
  rawText = genActOutput;
} else {
  rawText = JSON.stringify(genActOutput);
}
const chapter = extractChapter(rawText);
const inputData = $node["inject_state"].json;

return [{
  json: {
    id_story: inputData.id_story,    
    act_number: inputData.act_number,
    arc_phase: inputData.arc_phase,

    act_mission: inputData.act_mission,

    accumulated_memory: inputData.accumulated_memory,
    accumulated_summary: inputData.accumulated_summary,

    story_context: inputData.story_context,
    chapter: chapter
  }
}];

// Tomar el item original desde el loop
const original = $item(0).$node["Loop Over Items"].json;

// Devolverlo intacto
return [
  {
    json: { ...original }
  }
];

const raw = $input.item.json.response ?? $input.item.json.text ?? $input.item.json.output ?? "";

const jsonMatch = raw.match(/\{[\s\S]*?"chapter"\s*:\s*"([\s\S]*?)"\s*\}(?:\s*)$/);

if (jsonMatch) {
  const chapterText = jsonMatch[1]
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
    .trim();
  return [{ json: { ...($input.item.json), chapter: chapterText } }];
}

// Fallback: JSON.parse sobre el último bloque
const jsonBlocks = raw.match(/\{[\s\S]*?"chapter"[\s\S]*?\}/g);
if (jsonBlocks) {
  try {
    const parsed = JSON.parse(jsonBlocks[jsonBlocks.length - 1]);
    if (parsed.chapter) {
      return [{ json: { ...($input.item.json), chapter: parsed.chapter.trim() } }];
    }
  } catch (_) {}
}

return [{ json: { ...($input.item.json), chapter: raw.trim(), parse_error: true } }];

const raw = $input.item.json.response ?? $input.item.json.text ?? $input.item.json.output ?? "";

// Buscar el último bloque JSON que contenga "location" (el estado narrativo)
const jsonBlocks = raw.match(/\{[\s\S]*?"location"[\s\S]*?\}/g);
if (jsonBlocks) {
  try {
    const state = JSON.parse(jsonBlocks[jsonBlocks.length - 1]);
    return [{ json: { ...($input.item.json), narrative_state: state } }];
  } catch (_) {}
}

// Fallback: regex campo por campo
const extract = (key) => {
  const m = raw.match(new RegExp(`"${key}"\\s*:\\s*"([^"]*?)"`));
  return m ? m[1] : "";
};
const extractArray = (key) => {
  const m = raw.match(new RegExp(`"${key}"\\s*:\\s*\\[([^\\]]*?)\\]`));
  if (!m) return [];
  return m[1].match(/"([^"]+)"/g)?.map(s => s.replace(/"/g, '')) ?? [];
};

return [{
  json: {
    ...($input.item.json),
    narrative_state: {
      location:      extract("location"),
      characters:    extractArray("characters"),
      situation:     extract("situation"),
      active_threat: extract("active_threat"),
      goal:          extract("goal"),
      last_action:   extract("last_action"),
    },
    parse_error: true
  }
}];
